+    {
+        if (id == "D400") return RS2_PRODUCT_LINE_D400;
+        else if (id == "SR300") return RS2_PRODUCT_LINE_SR300;
+        else if (id == "L500") return RS2_PRODUCT_LINE_L500;
+        else return -1;
+    }
