+    inline bool equal(const std::string& a, const std::string& b)
+    {
+        return strcasecmp(a.c_str(), b.c_str()) == 0;
+    }
+
+    inline bool operator==(const device_id& a, const device_id& b)
+    {
+        return equal(a.pid, b.pid) &&
+            equal(a.guid, b.guid) &&
+            equal(a.mi, b.mi) &&
+            equal(a.sn, b.sn);
+    }
