+    public:
+        stream_dashboard(std::string name, int size) : q(size), name(name), t([this](){ thread_function(); }) {}
+        virtual ~stream_dashboard()
+        {
+            stop = true;
+            t.join();
+        }
+
+        std::string get_name() const { return name; }
+
+        void add_frame(rs2::frame f) { q.enqueue(f); }
