+// If you don't want to see debugging output for each received frame, then comment out the following line:
+#define DEBUG_PRINT_EACH_RECEIVED_FRAME 0
+
+void RsSink::afterGettingFrame(unsigned t_frameSize, unsigned t_numTruncatedBytes,
+                               struct timeval t_presentationTime, unsigned /*t_durationInMicroseconds*/)
+{
+  // We've just received a frame of data.  (Optionally) print out information about it:
+  /*
+#ifdef DEBUG_PRINT_EACH_RECEIVED_FRAME
+  if (fStreamId != NULL) envir() << "Stream \"" << fStreamId << "\"; ";
+  envir() << fSubsession.mediumName() << "/" << fSubsession.codecName() << ":\tReceived " << frameSize << " bytes";
+  if (numTruncatedBytes > 0) envir() << " (with " << numTruncatedBytes << " bytes truncated)";
+  char uSecsStr[6+1]; // used to output the 'microseconds' part of the presentation time
+  sprintf(uSecsStr, "%06u", (unsigned)presentationTime.tv_usec);
+  envir() << ".\tPresentation time: " << (int)presentationTime.tv_sec << "." << uSecsStr;
+  if (fSubsession.rtpSource() != NULL && !fSubsession.rtpSource()->hasBeenSynchronizedUsingRTCP()) {
+    envir() << "!"; // mark the debugging output to indicate that this presentation time is not RTCP-synchronized
+  }
+#ifdef DEBUG_PRINT_NPT
+  envir() << "\tNPT: " << fSubsession.getNormalPlayTime(presentationTime);
+#endif
+  envir() << "\n";
+#endif
+*/
+  RsNetworkHeader *header = (RsNetworkHeader *)m_receiveBuffer;
+  if (header->frameSize == t_frameSize - sizeof(RsNetworkHeader))
+  {
+    if (this->m_rtpCallback != NULL)
+    {
+#ifdef STATISTICS
+      StreamStatistic *st = Statistic::getStatisticStreams()[m_stream.type];
+      st->m_frameCounter++;
+      std::chrono::system_clock::time_point clockBegin = std::chrono::system_clock::now();
+      st->m_clockBeginVec.push(clockBegin);
+      if (st->m_frameCounter > 1)
+      {
+        st->m_getFrameDiffTime = clockBegin - st->m_prevClockBegin;
+        st->m_avgGettingTime += st->m_getFrameDiffTime.count();
+        printf("STATISTICS: streamType: %d, got frame: %0.2fm, average: %0.2fm, counter %d\n", m_stream.type, st->m_getFrameDiffTime.count() * 1000,
+               (st->m_avgGettingTime * 1000) / st->m_frameCounter, st->m_frameCounter);
+      }
+      st->m_prevClockBegin = clockBegin;
+#endif
+    if (CompressionFactory::isCompressionSupported(m_stream.fmt,m_stream.type) && m_iCompress != nullptr) 
+      {
+        m_to = m_memPool->getNextMem();
+        if (m_to == nullptr)
+        {
+          return;
+        }
+        int decompressedSize = m_iCompress->decompressBuffer(m_receiveBuffer + sizeof(RsFrameHeader), header->frameSize - sizeof(RsMetadataHeader), m_to + sizeof(RsFrameHeader));
+        if (decompressedSize != -1)
+        {
+          // copy metadata
+          memcpy(m_to + sizeof(RsNetworkHeader), m_receiveBuffer + sizeof(RsNetworkHeader), sizeof(RsMetadataHeader));
+          this->m_rtpCallback->on_frame((u_int8_t *)m_to + sizeof(RsNetworkHeader), decompressedSize + sizeof(RsMetadataHeader), t_presentationTime);
+        }
+        m_memPool->returnMem(m_receiveBuffer);
+      } 
+      else 
+      {
+        this->m_rtpCallback->on_frame(m_receiveBuffer + sizeof(RsNetworkHeader), header->frameSize, t_presentationTime);
+      }
+    }
+    else
+    {
+      // TODO: error, no call back
+      m_memPool->returnMem(m_receiveBuffer);
+      envir() << "Frame call back is NULL\n";
+    }
+  }
+  else
+  {
+    m_memPool->returnMem(m_receiveBuffer);
+    envir() << m_streamId << ":corrupted frame!!!: data size is " << header->frameSize << " frame size is " << t_frameSize << "\n";
+    //printf("%p:corrupted frame!!!: data size is %d frame size is %d \n",fStreamId,header->size,frameSize);
+  }
+  m_receiveBuffer = nullptr;
+  //fwrite(fReceiveBuffer, frameSize, 1, fp);
+  // Then continue, to request the next frame of data
+  continuePlaying();
+}
+
+Boolean RsSink::continuePlaying()
+{
+  if (fSource == NULL)
+    return False; // sanity check (should not happen)
+
+  // Request the next frame of data from our input source.  "afterGettingFrame()" will get called later, when it arrives:
+  m_receiveBuffer = m_memPool->getNextMem();
+  if (m_receiveBuffer == nullptr)
+  {
+    return false;
+  }
+
+  if (m_stream.uid >= 0 && m_stream.uid < m_afterGettingFunctions.size())
+  {
+    fSource->getNextFrame(m_receiveBuffer, m_bufferSize,
+                          m_afterGettingFunctions.at(m_stream.uid), this,
+                          onSourceClosure, this);
+  }
+  else
+  {
+    return false;
+  }
+
+  return True;
+}
+
+void RsSink::setCallback(rtp_callback *t_callback)
+{
+  this->m_rtpCallback = t_callback;
+}

