+      for (subsamp = 0; subsamp < TJ.NUMSAMP; subsamp++) {
+        for (w = 1; w < 48; w++) {
+          int maxh = (w == 1) ? 2048 : 48;
+          for (h = 1; h < maxh; h++) {
