+  public static void main(String[] argv) {
+    try {
+      String testName = "javatest";
+      for (int i = 0; i < argv.length; i++) {
+        if (argv[i].equalsIgnoreCase("-yuv"))
+          doYUV = true;
+        else if (argv[i].equalsIgnoreCase("-noyuvpad"))
