+#include <unistd.h>
+#include <dlfcn.h>
+
+#include "hidapi.h"
+
+/* Barrier implementation because Mac OSX doesn't have pthread_barrier.
+ It also doesn't have clock_gettime(). So much for POSIX and SUSv2.
+ This implementation came from Brent Priddy and was posted on
+ StackOverflow. It is used with his permission. */
+typedef int pthread_barrierattr_t;
+typedef struct pthread_barrier {
+    pthread_mutex_t mutex;
+    pthread_cond_t cond;
+    int count;
+    int trip_count;
+} pthread_barrier_t;
+
+static int pthread_barrier_init(pthread_barrier_t *barrier, const pthread_barrierattr_t *attr, unsigned int count)
+{
+    if(count == 0) {
+        errno = EINVAL;
+        return -1;
+    }
+    
+    if(pthread_mutex_init(&barrier->mutex, 0) < 0) {
+        return -1;
+    }
+    if(pthread_cond_init(&barrier->cond, 0) < 0) {
+        pthread_mutex_destroy(&barrier->mutex);
+        return -1;
+    }
+    barrier->trip_count = count;
+    barrier->count = 0;
+    
+    return 0;
+}
+
+static int pthread_barrier_destroy(pthread_barrier_t *barrier)
+{
+    pthread_cond_destroy(&barrier->cond);
+    pthread_mutex_destroy(&barrier->mutex);
+    return 0;
+}
+
+static int pthread_barrier_wait(pthread_barrier_t *barrier)
+{
+    pthread_mutex_lock(&barrier->mutex);
+    ++(barrier->count);
+    if(barrier->count >= barrier->trip_count)
+    {
+        barrier->count = 0;
+        pthread_cond_broadcast(&barrier->cond);
+        pthread_mutex_unlock(&barrier->mutex);
+        return 1;
+    }
+    else
+    {
+        pthread_cond_wait(&barrier->cond, &(barrier->mutex));
+        pthread_mutex_unlock(&barrier->mutex);
+        return 0;
+    }
+}
+
+static int return_data(hidapi_device *dev, unsigned char *data, size_t length);
+
+/* Linked List of input reports received from the device. */
+struct input_report {
+    uint8_t *data;
+    size_t len;
+    struct input_report *next;
+};
+
+struct hid_device_ {
+    IOHIDDeviceRef device_handle;
+    int blocking;
+    int uses_numbered_reports;
+    int disconnected;
+    CFStringRef run_loop_mode;
+    CFRunLoopRef run_loop;
+    CFRunLoopSourceRef source;
+    uint8_t *input_report_buf;
+    CFIndex max_input_report_len;
+    struct input_report *input_reports;
+    
+    pthread_t thread;
+    pthread_mutex_t mutex; /* Protects input_reports */
+    pthread_cond_t condition;
+    pthread_barrier_t barrier; /* Ensures correct startup sequence */
+    pthread_barrier_t shutdown_barrier; /* Ensures correct shutdown sequence */
+    int shutdown_thread;
+};
+
+static hidapi_device *new_hid_device(void)
+{
+    hidapi_device *dev = (hidapi_device *)calloc(1, sizeof(hidapi_device));
+    dev->device_handle = NULL;
+    dev->blocking = 1;
+    dev->uses_numbered_reports = 0;
+    dev->disconnected = 0;
+    dev->run_loop_mode = NULL;
+    dev->run_loop = NULL;
+    dev->source = NULL;
+    dev->input_report_buf = NULL;
+    dev->input_reports = NULL;
+    dev->shutdown_thread = 0;
+    
+    /* Thread objects */
+    pthread_mutex_init(&dev->mutex, NULL);
+    pthread_cond_init(&dev->condition, NULL);
+    pthread_barrier_init(&dev->barrier, NULL, 2);
+    pthread_barrier_init(&dev->shutdown_barrier, NULL, 2);
+    
+    return dev;
+}
+
+static void free_hid_device(hidapi_device *dev)
+{
+    if (!dev)
+        return;
+    
+    /* Delete any input reports still left over. */
+    struct input_report *rpt = dev->input_reports;
+    while (rpt) {
+        struct input_report *next = rpt->next;
+        free(rpt->data);
+        free(rpt);
+        rpt = next;
+    }
+    
+    /* Free the string and the report buffer. The check for NULL
+     is necessary here as CFRelease() doesn't handle NULL like
+     free() and others do. */
+    if (dev->run_loop_mode)
+        CFRelease(dev->run_loop_mode);
+    if (dev->source)
+        CFRelease(dev->source);
+    free(dev->input_report_buf);
+    
+    /* Clean up the thread objects */
+    pthread_barrier_destroy(&dev->shutdown_barrier);
+    pthread_barrier_destroy(&dev->barrier);
+    pthread_cond_destroy(&dev->condition);
+    pthread_mutex_destroy(&dev->mutex);
+    
+    /* Free the structure itself. */
+    free(dev);
+}
+
