+static transformation to_transform(const double R[9], const double t[3]) {
+    transformation tf;
+    for(int r=0; r<9; ++r){ tf.rotation[r] = static_cast<float>(R[r]); }
+    for(int i=0; i<3; ++i){ tf.translation[i] = static_cast<float>(t[i]); }
+    return tf;
