+/** Converts an unaligned four-byte little-endian integer into an int32 */
+#define DW_TO_INT(p) ((p)[0] | ((p)[1] << 8) | ((p)[2] << 16) | ((p)[3] << 24))
+/** Converts an unaligned two-byte little-endian integer into an int16 */
+#define SW_TO_SHORT(p) ((p)[0] | ((p)[1] << 8))
+/** Converts an unaligned eight-byte little-endian integer into an int64 */
+#define QW_TO_QUAD(p) (((uint64_t)(p)[0]) | \
+                      (((uint64_t)(p)[1]) << 8) | \
+                      (((uint64_t)(p)[2]) << 16) | \
+                      (((uint64_t)(p)[3]) << 24) | \
+                      (((uint64_t)(p)[4]) << 32) | \
+                      (((uint64_t)(p)[5]) << 40) | \
+                      (((uint64_t)(p)[6]) << 48) | \
+                      (((uint64_t)(p)[7]) << 56))
+
+/** Converts an int16 into an unaligned two-byte little-endian integer */
+#define SHORT_TO_SW(s, p) \
+  (p)[0] = (uint8_t)(s); \
+  (p)[1] = (uint8_t)((s) >> 8);
+/** Converts an int32 into an unaligned four-byte little-endian integer */
+#define INT_TO_DW(i, p) \
+  (p)[0] = (uint8_t)(i); \
+  (p)[1] = (uint8_t)((i) >> 8); \
+  (p)[2] = (uint8_t)((i) >> 16); \
+  (p)[3] = (uint8_t)((i) >> 24);
+
+/** Converts an int64 into an unaligned eight-byte little-endian integer */
+#define QUAD_TO_QW(i, p) \
+  (p)[0] = (uint8_t)(i); \
+  (p)[1] = (uint8_t)((i) >> 8); \
+  (p)[2] = (uint8_t)((i) >> 16); \
+  (p)[3] = (uint8_t)((i) >> 24); \
+  (p)[4] = (uint8_t)((i) >> 32); \
+  (p)[5] = (uint8_t)((i) >> 40); \
+  (p)[6] = (uint8_t)((i) >> 48); \
+  (p)[7] = (uint8_t)((i) >> 56); \
+
+/** Selects the nth item in a doubly linked list. n=-1 selects the last item. */
+#define DL_NTH(head, out, n) \
+do \
+{ \
+    int dl_nth_i = 0; \
+    LDECLTYPE(head) dl_nth_p = (head); \
+    if ((n) < 0) \
+    { \
+        while (dl_nth_p && dl_nth_i > (n)) \
+        { \
+        dl_nth_p = dl_nth_p->prev; \
+        dl_nth_i--; \
+                                                                } \
+    } \
+    else \
+    { \
+        while (dl_nth_p && dl_nth_i < (n)) \
+        { \
+        dl_nth_p = dl_nth_p->next; \
+        dl_nth_i++; \
+                                                                                                                                                } \
+                    } \
+    (out) = dl_nth_p; \
+          } while (0);

