+                                                                     jobject buffer) {
+    rs2::config cfg;
+    output = env->GetDirectBufferAddress(buffer);
+    cfg.enable_stream(RS2_STREAM_DEPTH, 848, 480);
+    profile = p.start(cfg);
+    isStreaming = true;
+    sleep(2);
+    t = std::thread(call_from_thread);
+    return true;
+}
