+
+JNIEXPORT jboolean JNICALL
+Java_com_intel_realsense_libusbhost_MainActivity_librsStopStreaming(JNIEnv *env,
+                                                                    jobject instance) {
+
+    if (isStreaming) {
+        t.join();
+        p.stop();
+        isStreaming = false;
+    }
+    return true;
