+  (p)[0] = (uint8_t)(i); \
+  (p)[1] = (uint8_t)((i) >> 8); \
+  (p)[2] = (uint8_t)((i) >> 16); \
+  (p)[3] = (uint8_t)((i) >> 24); \
+  (p)[4] = (uint8_t)((i) >> 32); \
+  (p)[5] = (uint8_t)((i) >> 40); \
+  (p)[6] = (uint8_t)((i) >> 48); \
