+void FRuntimeMeshCollisionCookTickObject::Tick(float DeltaTime)
+{
+	URuntimeMesh* Mesh = Owner.Get();
+	if (Mesh && Mesh->bCollisionIsDirty)
+	{
+		Mesh->UpdateCollision();
+		Mesh->bCollisionIsDirty = false;
+	}
+}
