+void URuntimeMesh::SendSectionCreation(int32 SectionIndex)
+{
+	DoForAllLinkedComponents([SectionIndex](URuntimeMeshComponent* Mesh)
+	{
+		Mesh->SendSectionCreation(SectionIndex);
+	});
