+		for (int32 UVIndex = 0; UVIndex < NumUVs; UVIndex++)
+		{
+			Other->SetUV(NewIndex, UVIndex, GetUV(Index, UVIndex));
+		}
+	}
+
+	int32 NumInds = NumIndices();
+	for (int32 Index = 0; Index < NumInds; Index++)
+	{
+		Other->AddIndex(GetIndex(Index) + StartVertex);
+	}
+}
