+
+	FRuntimeMeshScopeLock Lock(SyncRoot);
+
+	MeshSections.Empty();
+
+	if (RenderProxy.IsValid())
+	{
+		RenderProxy->DeleteSection_GameThread(INDEX_NONE);
+	}
+
+	UpdateLocalBounds();
+	MarkRenderStateDirty();
+	MarkCollisionDirty();
+}
