+		template<typename VertexType>
+		void SetData(const TArray<VertexType>& InVertices)
+		{
+			if (InVertices.Num() == 0)
+			{
+				Data.Empty();
+				return;
+			}
+			check(InVertices.GetTypeSize() == GetStride());
+
+			Data.SetNum(InVertices.GetTypeSize() * InVertices.Num());
