+			if (Ar.CustomVer(FRuntimeMeshVersion::GUID) < FRuntimeMeshVersion::RuntimeMeshComponentUE4_19)
+			{
+				FRuntimeMeshVertexStreamStructure VertexStructure;
+				Ar << const_cast<FRuntimeMeshVertexStreamStructure&>(VertexStructure);
