+
+
+  static NAN_METHOD(SupportsCameraInfo) {
+    int32_t camera_info = info[0]->IntegerValue();
+    auto me = Nan::ObjectWrap::Unwrap<RSDevice>(info.Holder());
+    if (me) {
+      int32_t on = rs2_supports_device_info(me->dev,
