+ private:
+  RSPipeline() {
+    error = nullptr;
+    pipeline = nullptr;
+  }
+
+  ~RSPipeline() {
+    DestroyMe();
+  }
+
+  void DestroyMe() {
+    if (error) rs2_free_error(error);
+    error = nullptr;
+    if (pipeline) rs2_delete_pipeline(pipeline);
+    pipeline = nullptr;
+
+  }
+
+  static NAN_METHOD(Destroy) {
+    auto me = Nan::ObjectWrap::Unwrap<RSPipeline>(info.Holder());
+    if (me) {
+      me->DestroyMe();
+    }
+    info.GetReturnValue().Set(Nan::Undefined());
+  }
+
+  static void New(const Nan::FunctionCallbackInfo<v8::Value>& info) {
+    if (info.IsConstructCall()) {
+      RSPipeline* obj = new RSPipeline();
+      obj->Wrap(info.This());
+      info.GetReturnValue().Set(info.This());
+    }
+  }
+
+  static NAN_METHOD(Create) {
+    auto me = Nan::ObjectWrap::Unwrap<RSPipeline>(info.Holder());
+    auto rsctx = Nan::ObjectWrap::Unwrap<RSContext>(info[0]->ToObject());
+
+    if (me && rsctx) {
+      if (info[1]->IsUndefined()) {
+        me->pipeline = rs2_create_pipeline(rsctx->ctx, &me->error);
+      } else {
+        auto rsdev = Nan::ObjectWrap::Unwrap<RSDevice>(info[1]->ToObject());
+        me->pipeline = rs2_create_pipeline_with_device(rsctx->ctx, rsdev->dev, &me->error);
+      }
+    }
+    info.GetReturnValue().Set(Nan::Undefined());
+  }
+
+  static NAN_METHOD(Start) {
+    auto me = Nan::ObjectWrap::Unwrap<RSPipeline>(info.Holder());
+    if (me && me->pipeline) {
+      rs2_start_pipeline(me->pipeline, &me->error);
+    }
+    info.GetReturnValue().Set(Nan::Undefined());
+  }
+
+  static NAN_METHOD(Stop) {
+    auto me = Nan::ObjectWrap::Unwrap<RSPipeline>(info.Holder());
+    if (me && me->pipeline) {
+      rs2_stop_pipeline(me->pipeline, &me->error);
+    }
+    info.GetReturnValue().Set(Nan::Undefined());
+  }
+
+  static NAN_METHOD(WaitForFrames) {
+    auto me = Nan::ObjectWrap::Unwrap<RSPipeline>(info.Holder());
+    auto timeout = info[0]->IntegerValue();
+    if (me) {
+      rs2_frame* frames = rs2_pipeline_wait_for_frames(me->pipeline, timeout, &me->error);
+      if (frames) {
+        info.GetReturnValue().Set(RSFrameSet::NewInstance(frames));
+        return;
+      }
+    }
+    info.GetReturnValue().Set(Nan::Undefined());
+  }
+ private:
+  static Nan::Persistent<v8::Function> constructor;
+
+  rs2_pipeline* pipeline;
+  rs2_error* error;
