+		
+	for (; i < superPixCount; i += stride) {
+
+        int idx = i * 4;
+
+        dst[idx] = 0;
+        dst[idx + 1] = src[idx + 0];
+        dst[idx + 2] = 0;
+        dst[idx + 3] = src[idx + 2];
+    }
+}
