+                converter->convert(frameset);
+            });
+
+        for_each(converters.begin(), converters.end(),
+            [] (shared_ptr<rs2::tools::converter::converter_base>& converter) {
+                converter->wait();
+            });
+    }
+
+    cout << endl;
+
+    for_each(converters.begin(), converters.end(),
+        [] (shared_ptr<rs2::tools::converter::converter_base>& converter) {
+            cout << converter->get_statistics() << endl;
+        });
