+        << "(" << e.get_failed_args() << "):\n    " << e.what() << endl;
+
+    return EXIT_FAILURE;
+}
+catch (const exception & e)
+{
+    cerr << e.what() << endl;
+    return EXIT_FAILURE;
+}
+catch (...)
+{
+    cerr << "some error" << endl;
+    return EXIT_FAILURE;
+}

