+std::vector<uint32_t> split(const std::string &s, char delim) {
+    std::stringstream ss(s);
+    std::string item;
+    std::vector<uint32_t> tokens;
+    while (std::getline(ss, item, delim)) {
+        tokens.push_back(std::stoi(item, nullptr));
+    }
+    return tokens;
