+'use strict';
+
+/* global describe, it */
+const assert = require('assert');
+const EventEmitter = require('events');
+const librealsense2 = require('../index.js');
+
+describe('Context test', function() {
+  it('testing constructor', () => {
+    assert.doesNotThrow(() => {
+      new librealsense2.Context();
+    });
+    assert.throws(() => {
+      new librealsense2.Context(123);
+    });
+    assert.throws(() => {
+      new librealsense2.Context('dummy');
+    });
+    const context = new librealsense2.Context();
+    assert.equal(typeof context, 'object');
+  });
+
+  it('testing member - events', () => {
+    const context = new librealsense2.Context();
+    assert(context._events instanceof EventEmitter);
+  });
+
+  it('testing method - createPointcloud, should get Pointcloud', () => {
+    const context = new librealsense2.Context();
+    let pointcloud;
+    assert.doesNotThrow(() => {
+      pointcloud = context.createPointcloud();
+    });
+    assert(pointcloud instanceof librealsense2.Pointcloud);
+  });
+
+  it('testing method - createPointcloud, invalid 1 option', () => {
+    const context = new librealsense2.Context();
+    let pointcloud;
+    assert.doesNotThrow(() => {
+      pointcloud = context.createPointcloud(1);
+    });
+    assert(pointcloud instanceof librealsense2.Pointcloud);
+  });
+
+  it('testing method - destroy, call 1 time', () => {
+    assert.doesNotThrow(() => {
+      const context = new librealsense2.Context();
+      context.destroy();
+    });
+    assert.doesNotThrow(() => {
+      const context = new librealsense2.Context();
+      context.destroy(123);
+    });
+  });
+
+  it('testing method - destroy, call 2 times', () => {
+    assert.throws(() => {
+      const context = new librealsense2.Context();
+      context.destroy();
+      context.destroy();
+    });
+  });
+
+  it('testing method - getTime, should get number value', () => {
+    const context = new librealsense2.Context();
+    assert.doesNotThrow(() => {
+      context.getTime();
+    });
+    assert.equal(typeof context.getTime(), 'number');
+  });
+
