+static const char *_uvc_name_for_format_subtype(uint8_t subtype) {
+  switch (subtype) {
+  case UVC_VS_FORMAT_UNCOMPRESSED:
+    return "UncompressedFormat";
+  case UVC_VS_FORMAT_MJPEG:
+    return "MJPEGFormat";
+  case UVC_VS_FORMAT_FRAME_BASED:
+    return "FrameFormat";
+  default:
+    return "Unknown";
+  }
+}
