+	enum class FrameFormat {
+		UNKNOWN = 0,
+		ANY = 0, // Any supported format
+		UNCOMPRESSED,
+		COMPRESSED,
+		YUYV, // YUYV/YUV2/YUV422: YUV encoding with one luminance value per pixel and one UV (chrominance) pair for every two pixels.
