+		Y12I,
+		Y16,
+		Y8,
+		Z16,
+		RGB,
+		BGR,
+		MJPEG,
+		GRAY8,
+		BY8,
+		INVI, //IR
+		RELI, //IR
+		INVR, //Depth
+		INVZ, //Depth
+		INRI, //Depth (24 bit)
+		COUNT
+	};
